class Solution {
    public long minCost(int[] nums, int[] costs) {
        int n = nums.length;
        int[] ng = new int[n], nl = new int[n];
        Arrays.fill(ng, n); Arrays.fill(nl, n);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && nums[st.peek()] < nums[i]) st.pop();
            ng[i] = st.isEmpty() ? n : st.peek();
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && nums[st.peek()] >= nums[i]) st.pop();
            nl[i] = st.isEmpty() ? n : st.peek();
            st.push(i);
        }
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        for (int i = 0; i < n; i++) {
            if (ng[i] < n) dist[ng[i]] = Math.min(dist[ng[i]], dist[i] + costs[ng[i]]);
            if (nl[i] < n) dist[nl[i]] = Math.min(dist[nl[i]], dist[i] + costs[nl[i]]);
        }
        return dist[n - 1];
    }
}

