import heapq
class Solution:
    def minCost(self, nums, costs):
        n = len(nums)
        adj = [[] for _ in range(n)]
        st = []
        ng = [n] * n
        nl = [n] * n
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] < nums[i]: st.pop()
            ng[i] = st[-1] if st else n
            st.append(i)
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] >= nums[i]: st.pop()
            nl[i] = st[-1] if st else n
            st.append(i)
        for i in range(n):
            if ng[i] < n: adj[i].append(ng[i])
            if nl[i] < n: adj[i].append(nl[i])
        dist = [float('inf')] * n
        dist[0] = 0
        pq = [(0, 0)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]: continue
            for v in adj[u]:
                nd = d + costs[v]
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        return dist[n - 1]

