class Solution {
public:
    long long minCost(vector<int>& nums, vector<int>& costs) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        vector<int> st, ng(n, n), nl(n, n);
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && nums[st.back()] < nums[i]) st.pop_back();
            ng[i] = st.empty() ? n : st.back(); st.push_back(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
            nl[i] = st.empty() ? n : st.back(); st.push_back(i);
        }
        for (int i = 0; i < n; i++) {
            if (ng[i] < n) adj[i].push_back(ng[i]);
            if (nl[i] < n) adj[i].push_back(nl[i]);
        }
        vector<long long> dist(n, LLONG_MAX);
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        dist[0] = 0; pq.push({0, 0});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (int v : adj[u]) {
                if (d + costs[v] < dist[v]) {
                    dist[v] = d + costs[v];
                    pq.push({dist[v], v});
                }
            }
        }
        return dist[n - 1];
    }
};

