class Solution {
    public long minCost(int[] nums, int[] costs) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        Deque<Integer> st = new ArrayDeque<>();
        int[] ng = new int[n], nl = new int[n];
        Arrays.fill(ng, n); Arrays.fill(nl, n);
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && nums[st.peek()] < nums[i]) st.pop();
            ng[i] = st.isEmpty() ? n : st.peek(); st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && nums[st.peek()] >= nums[i]) st.pop();
            nl[i] = st.isEmpty() ? n : st.peek(); st.push(i);
        }
        for (int i = 0; i < n; i++) {
            if (ng[i] < n) adj.get(i).add(ng[i]);
            if (nl[i] < n) adj.get(i).add(nl[i]);
        }
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        dist[0] = 0; pq.offer(new long[]{0, 0});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0]; int u = (int) top[1];
            if (d > dist[u]) continue;
            for (int v : adj.get(u)) {
                if (d + costs[v] < dist[v]) {
                    dist[v] = d + costs[v];
                    pq.offer(new long[]{dist[v], v});
                }
            }
        }
        return dist[n - 1];
    }
}

